#include <vector>

using namespace std;

class Solution {
public:
    int waysToSplit(vector<int>& nums) {
        const int MOD = 1e9 + 7;
        int n = nums.size();
        vector<int> prefix(n);
        prefix[0] = nums[0];
        for (int i = 1; i < n; ++i)
            prefix[i] = prefix[i - 1] + nums[i];

        int res = 0, j = 0, k = 0;
        for (int i = 0; i < n - 2; ++i) {
            j = max(j, i + 1);
            while (j < n - 1 && prefix[j] < 2 * prefix[i]) ++j;
            k = max(k, j);
            while (k < n - 1 && prefix[k] - prefix[i] <= prefix[n - 1] - prefix[k]) ++k;
            res = (res + max(0, k - j)) % MOD;
        }
        return res;
    }
};
